# Action Masking & Action Selection
# Action masking ensures that invalid moves generated by rules.py get set to -infinity logit probability so the network never picks illegal actions.

import math
import torch
import numpy as np
import rules

def get_masked_policy(model, fen):
    """
    Converts fen via rules.py, gets NN output, and masks out illegal moves.
    """
    # Step 1: Setting the Model to Evaluation Mode (model.eval())
    # Puts PyTorch into inference/evaluation mode. It deactivates layers like Dropout 
    # and sets Batch Normalization to use frozen running statistics instead of recalculating 
    # them per batch, ensuring consistent, deterministic network outputs during gameplay.
        
    model.eval()
    
    # Step 2: Translating and Batching the fen (fen_to_tensor + unsqueeze(0))
    # Calls the encoder to convert the current fen into the multi-channel 
    # tensor format, then adds a leading batch dimension. PyTorch models are optimized 
    # to process batches shaped (Batch_Size, Channels, Height, Width). Since we are evaluating 
    # a single fen, unsqueeze(0) changes the shape from (C, 10, 10) to (1, C, 10, 10).
    
    fen_tensor = encoder.fen_to_tensor(rules.fen()).unsqueeze(0)  
    
    # Step 3: Running Inference Without Gradients (with torch.no_grad():)
    # Passes the fen tensor through the TactalarisNet model to get raw unnormalized move 
    # scores (logits) and board evaluation (value) without backpropagation. Disabling 
    # gradients saves massive memory and speeds up CPU execution on your Mac Mini M2.
    
    with torch.no_grad():
        logits, value = model(fen_tensor)
        logits = logits.squeeze(0)  # Remove batch dimension from output tensor
    
    # Step 4: Fetching Legal Moves from the Rule Engine (rules.get_legal_moves)
    # Asks your rules.py library to calculate every physically valid move available to 
    # the current player in this specific position, acting as the single source of truth.
    
    rules.load({"fen": fen})
    legal_moves = rules.get_legal_moves()
    
    # Step 5: Mapping Moves to Network Indices (rules.move_to_index)
    # Converts each high-level move object returned by the rules engine into its corresponding 
    # integer index in the network's flat output action vector (e.g., index 42 out of 500).
    
    legal_indices = [encoder.move_to_index(m) for m in legal_moves]
    
    # Step 6: Constructing the Action Mask (torch.full_like)
    # Generates a tensor filled entirely with negative infinity (-inf) matching the size of the 
    # network's output logits. In PyTorch, adding 0.0 leaves a logit untouched, while adding -inf 
    # forces it to drop to absolute zero probability. We place 0.0 only at legal move indices.
    
    mask = torch.full_like(logits, float('-inf'))
    mask[legal_indices] = 0.0
    
    # Step 7: Applying the Mask and Softmax (logits + mask -> softmax)
    # Adds the mask directly to raw network logits, then applies Softmax. Illegal move logits 
    # become -inf (zeroing probability), while legal move logits retain their relative confidence 
    # scores and are normalized into a clean probability distribution summing to 1.0.
    
    masked_logits = logits + mask
    probs = torch.softmax(masked_logits, dim=-1)
    
    return probs, value.item(), legal_moves

def select_action(probs, legal_moves, temperature=1.0):
    """
    Samples an action based on temperature.
    """
    legal_indices = [encoder.move_to_index(m) for m in legal_moves]
    legal_probs = probs[legal_indices].numpy()
    
    if temperature == 0:
        best_idx = np.argmax(legal_probs)
        return legal_moves[best_idx]
    
    # Temperature scaling
    legal_probs = np.power(legal_probs, 1.0 / temperature)
    legal_probs /= np.sum(legal_probs)
    
    chosen_idx = np.random.choice(len(legal_moves), p=legal_probs)
    return legal_moves[chosen_idx]
